steps:
STEP 1 — Add five E-* evidence records to data/evidence.json (append to the 'evidence' array). Use retrieved date 2026-10-13.

  { id:'E-CPIC-TACROLIMUS-2015', org:'CPIC', title:'Clinical Pharmacogenetics Implementation Consortium (CPIC) Guidelines for CYP3A5 Genotype and Tacrolimus Dosing', url:'https://www.ncbi.nlm.nih.gov/pmc/articles/PMC4481158', year:'2015', type:'primary_guideline', retrieved:'2026-10-13', note:'CPIC tacrolimus/CYP3A5 guideline; covers dose increases for CYP3A5 expressors.' }

  { id:'E-CPIC-WARFARIN-2017', org:'CPIC', title:'Clinical Pharmacogenetics Implementation Consortium (CPIC) Guideline for Pharmacogenetics-Guided Warfarin Dosing: 2017 Update', url:'https://www.ncbi.nlm.nih.gov/pmc/articles/PMC5546947', year:'2017', type:'primary_guideline', retrieved:'2026-10-13', note:'CPIC warfarin guideline; multi-gene dosing algorithm for CYP2C9, VKORC1, CYP4F2.' }

  { id:'E-CPIC-TAMOXIFEN-2018', org:'CPIC', title:'Clinical Pharmacogenetics Implementation Consortium (CPIC) Guideline for CYP2D6 and Tamoxifen Therapy', url:'https://www.ncbi.nlm.nih.gov/pmc/articles/PMC5931215', year:'2018', type:'primary_guideline', retrieved:'2026-10-13', note:'CPIC tamoxifen/CYP2D6 guideline; alternative therapy for PM.' }

  { id:'E-CPIC-PPI-2021', org:'CPIC', title:'Clinical Pharmacogenetics Implementation Consortium (CPIC) Guideline for CYP2C19 and Proton Pump Inhibitor Dosing', url:'https://www.ncbi.nlm.nih.gov/pmc/articles/PMC7868475', year:'2021', type:'primary_guideline', retrieved:'2026-10-13', note:'CPIC PPI guideline; covers omeprazole, lansoprazole, pantoprazole and CYP2C19 UM dose adjustment.' }

  { id:'E-CPIC-VORI-2017', org:'CPIC', title:'Clinical Pharmacogenetics Implementation Consortium (CPIC) Guidelines for CYP2C19 Genotype and Voriconazole Therapy', url:'https://www.ncbi.nlm.nih.gov/pmc/articles/PMC5474211', year:'2017', type:'primary_guideline', retrieved:'2026-10-13', note:'CPIC voriconazole/CYP2C19 guideline; alternative agent for UM, dose reduction for PM.' }

STEP 2 — Append TACROLIMUS / CYP3A5 rule to data/rules/pgx.json. All rules: module='pgx', version='2.0.0', status='verified', evidenceLevel=null, blocking=true, onUnmetContext='conditional', requires={}.

  CYP3A5 phenotypes: normal (homozygous expresser, *1/*1), intermediate (heterozygous expresser, *1/*3), poor (non-expresser, *3/*3). CPIC and DPWG recommend an increased starting dose for expressors (normal + intermediate).

  R-PGX-TACROLIMUS-CYP3A5-EXPRESSER: condition={type:'pgx', gene:'CYP3A5', phenotypeIn:['normal','intermediate']}, action='modify', headline='Increased tacrolimus starting dose recommended for CYP3A5 expressors (normal/intermediate metabolizers)', rationale='CPIC recommends increasing the starting dose by 1.5 to 2 times the recommended starting dose for CYP3A5 expressors (CYP3A5*1 carriers); DPWG and RNPGx make the same recommendation. Dose must be individualised by TDM.', mechanism='CYP3A5 (*1 allele) metabolises tacrolimus extensively in the gut and liver; expressors have lower tacrolimus exposure at standard doses.', monitoring=['Therapeutic drug monitoring (TDM) is mandatory for tacrolimus; adjust dose to target trough concentrations per transplant protocol.'], limitations=['The fold-increase depends on transplant organ and protocol. No dose is calculated here. Liver transplant recipients require special consideration (donor CYP3A5 genotype matters for hepatic clearance).'], evidence=['E-CPIC-TACROLIMUS-2015','G:PA166124619','G:PA166104983','G:PA166202481'], alternatives={supported:false, text:'No alternative immunosuppressant is encoded; see the cited guidelines.'}

STEP 3 — Append WARFARIN rules to data/rules/pgx.json. Three separate gene rules for the same drug. Warfarin requires a multi-gene dosing algorithm; each rule flags a gene that alters the required dose.

  R-PGX-WARFARIN-CYP2C9-IMPM: condition={type:'pgx', gene:'CYP2C9', phenotypeIn:['intermediate','poor']}, action='modify', headline='Warfarin dose reduction advised for CYP2C9 intermediate/poor metabolizers', rationale='DPWG recommends reducing the warfarin dose in CYP2C9 poor and intermediate metabolizers; CPIC advises using a pharmacogenomics-guided dosing algorithm that incorporates CYP2C9 genotype.', mechanism='CYP2C9 metabolises (S)-warfarin; reduced activity raises warfarin exposure, increasing bleeding risk.', monitoring=['Frequent INR monitoring especially at initiation. Adjust dose by INR response and per a pharmacogenomics-guided algorithm.'], evidence=['E-CPIC-WARFARIN-2017','G:PA166104949','G:PA166182842'], alternatives={supported:false, text:'No specific alternative anticoagulant is encoded; see guidelines.'}

  R-PGX-WARFARIN-VKORC1-VARIANT: condition={type:'pgx', gene:'VKORC1', phenotypeIn:['variant_present']}, action='modify', headline='Warfarin dose reduction advised for VKORC1 variant carriers (increased sensitivity)', rationale='DPWG recommends 60% of the standard initial warfarin dose for VKORC1 rs9923231 TT genotype carriers (-1639 AA); CPIC includes VKORC1 in its pharmacogenomics dosing algorithm. Variant_present here corresponds to the dose-reducing allele.', mechanism='VKORC1 encodes the warfarin target; the -1639A allele reduces VKORC1 expression, making patients more sensitive to warfarin.', monitoring=['Frequent INR monitoring. Adjust dose to target INR using a pharmacogenomics-guided algorithm.'], evidence=['E-CPIC-WARFARIN-2017','G:PA166104949','G:PA166182841'], alternatives={supported:false}

  R-PGX-WARFARIN-CYP4F2-VARIANT: condition={type:'pgx', gene:'CYP4F2', phenotypeIn:['variant_present']}, action='modify', headline='Warfarin dose may need adjustment for CYP4F2 variant carriers', rationale='CPIC includes CYP4F2 rs2108622 in its warfarin dosing algorithm; the *3 variant reduces vitamin K recycling, potentially requiring a slightly higher dose. This modifies the direction of expected dose adjustment compared with CYP2C9/VKORC1.', mechanism='CYP4F2 metabolises vitamin K1; reduced CYP4F2 activity raises vitamin K availability, blunting warfarin effect slightly.', monitoring=['INR monitoring as for all warfarin patients.'], limitations=['The CYP4F2 variant effect on dose is modest and direction is opposite to CYP2C9/VKORC1 variants (may need higher dose). The full algorithm requires all gene inputs. No dose is calculated here.'], evidence=['E-CPIC-WARFARIN-2017','G:PA166104949'], alternatives={supported:false}

STEP 4 — Append TAMOXIFEN / CYP2D6 rules to data/rules/pgx.json.

  R-PGX-TAMOXIFEN-CYP2D6-PM: condition={type:'pgx', gene:'CYP2D6', phenotypeIn:['poor']}, action='modify', headline='Alternative hormonal therapy recommended for CYP2D6 poor metabolizers taking tamoxifen', rationale='CPIC recommends alternative hormonal therapy (aromatase inhibitor for postmenopausal women, or ovarian suppression plus aromatase inhibitor for premenopausal women) for CYP2D6 poor metabolizers, as reduced endoxifen formation compromises tamoxifen efficacy; DPWG recommends considering an alternative medication.', mechanism='CYP2D6 converts tamoxifen to endoxifen (the active metabolite); poor metabolizers have markedly reduced endoxifen levels and reduced anti-oestrogenic effect.', monitoring=['Consider endoxifen plasma level monitoring if tamoxifen is continued despite poor metabolizer status.'], limitations=['The evidence base is for breast cancer prevention/treatment; applicability to other indications is not established. CPIC recommendation is for postmenopausal vs premenopausal women; sex/menopausal status is not collected.'], evidence=['E-CPIC-TAMOXIFEN-2018','G:PA166176068','G:PA166104966'], alternatives={supported:true, text:'Aromatase inhibitor (postmenopausal) or ovarian suppression + aromatase inhibitor (premenopausal) per CPIC.', evidence:['G:PA166176068']}

  R-PGX-TAMOXIFEN-CYP2D6-IM: condition={type:'pgx', gene:'CYP2D6', phenotypeIn:['intermediate']}, action='modify', headline='Alternative or increased dose of tamoxifen advised for CYP2D6 intermediate metabolizers', rationale='DPWG recommends considering an alternative medication or a dose increase for CYP2D6 intermediate metabolizers and advises avoiding concomitant strong CYP2D6 inhibitors; CPIC also advises modification.', mechanism='Partial CYP2D6 activity reduces endoxifen formation, potentially reducing tamoxifen efficacy.', evidence=['E-CPIC-TAMOXIFEN-2018','G:PA166176068','G:PA166104966'], alternatives={supported:true, text:'Alternative hormonal therapy per CPIC; specific agents not encoded here.', evidence:['G:PA166176068']}

STEP 5 — Append PPI / CYP2C19 rules to data/rules/pgx.json. Two drugs (omeprazole, lansoprazole), same gene.

  R-PGX-OMEPRAZOLE-CYP2C19-UM: drug='omeprazole', condition={type:'pgx', gene:'CYP2C19', phenotypeIn:['ultrarapid','rapid']}, action='modify', headline='Increased omeprazole dose recommended for CYP2C19 ultrarapid/rapid metabolizers', rationale='CPIC recommends increasing the starting daily dose and monitoring efficacy in CYP2C19 ultrarapid metabolizers; DPWG recommends a 3-fold higher dose for H. pylori eradication therapy in CYP2C19 ultrarapid metabolizers and consideration of an alternative PPI for other indications.', mechanism='CYP2C19 is the primary enzyme metabolising omeprazole; ultrarapid/rapid metabolizers have lower drug exposure and reduced acid suppression.', monitoring=['Monitor clinical response (H. pylori eradication or symptom relief). TDM not routinely done for PPIs.'], limitations=['TODO: The DPWG summary for PM/IM of omeprazole is not fully retrievable from the available index; PM/IM rules are not encoded in this version. Re-check G:PA166104957 for complete recommendations.'], evidence=['E-CPIC-PPI-2021','G:PA166219103','G:PA166104957'], alternatives={supported:false}

  R-PGX-LANSOPRAZOLE-CYP2C19-UM: drug='lansoprazole', condition={type:'pgx', gene:'CYP2C19', phenotypeIn:['ultrarapid','rapid']}, action='modify', headline='Increased lansoprazole dose recommended for CYP2C19 ultrarapid/rapid metabolizers', rationale='CPIC recommends increasing the starting daily dose for CYP2C19 ultrarapid metabolizers; DPWG recommends a 4-fold higher dose for H. pylori eradication in CYP2C19 ultrarapid metabolizers.', mechanism='CYP2C19 is the primary enzyme metabolising lansoprazole; UM/rapid metabolizers have reduced acid suppression at standard doses.', limitations=['TODO: PM/IM rules for lansoprazole are not encoded in this version. Re-check G:PA166104987 for complete recommendations.'], evidence=['E-CPIC-PPI-2021','G:PA166219103','G:PA166104987'], alternatives={supported:false}

STEP 6 — Append VORICONAZOLE / CYP2C19 rules to data/rules/pgx.json.

  R-PGX-VORICONAZOLE-CYP2C19-UM: condition={type:'pgx', gene:'CYP2C19', phenotypeIn:['ultrarapid','rapid']}, action='modify', headline='Alternative antifungal or increased voriconazole dose recommended for CYP2C19 ultrarapid/rapid metabolizers', rationale='CPIC recommends selecting an alternative antifungal agent not dependent on CYP2C19 metabolism for adults who are CYP2C19 ultrarapid metabolizers; DPWG recommends a 1.5-fold higher dose; AusNZ recommends an alternative agent for known CYP2C19 ultrarapid metabolizers.', mechanism='CYP2C19 is the primary enzyme metabolising voriconazole; ultrarapid/rapid metabolizers have markedly reduced drug exposure and inadequate antifungal efficacy.', monitoring=['Therapeutic drug monitoring (TDM) is strongly recommended. Target voriconazole trough concentration per institutional protocol.'], evidence=['E-CPIC-VORI-2017','G:PA166161537','G:PA166104990','G:PA166257241'], alternatives={supported:true, text:'An alternative antifungal not dependent on CYP2C19 (CPIC); specific agents not encoded.', evidence:['G:PA166161537']}

  R-PGX-VORICONAZOLE-CYP2C19-PM: condition={type:'pgx', gene:'CYP2C19', phenotypeIn:['poor']}, action='modify', headline='Voriconazole dose reduction recommended for CYP2C19 poor metabolizers', rationale='DPWG recommends that CYP2C19 poor metabolizers receive 50% of the standard dose of voriconazole; CPIC notes elevated exposure in PM patients.', mechanism='Markedly reduced CYP2C19 activity causes voriconazole accumulation, raising toxicity risk (visual disturbances, hepatotoxicity).', monitoring=['TDM is strongly recommended. Target trough concentration per institutional protocol.'], evidence=['E-CPIC-VORI-2017','G:PA166161537','G:PA166104990'], alternatives={supported:false}

STEP 8 — Add reference test cases to tests/fixtures/reference_cases.js. Append to the CASES array:

